      SUBROUTINE IQOPEN
*     GENERATED BY FPL90 V(AIX V3.0 94- 1- 7)        AIX V3.0 94- 1-29
      IMPLICIT INTEGER(A-Z)
      LOGICAL IQFSRD
      INTEGER IQULVL,IQUNST(300),IQUNIT,IQUNUM(5),IQFSTN,IQLMAX(5),
     *IQLCLM(5),IQLNNO(5),IQLPGE(5)
      CHARACTER IQCDAT*24,IQVDAT*24,IQLCNT(5)*1,IQLINE(5)*136
      COMMON /IQCHRL/IQFSRD
      COMMON /IQCHRI/IQULVL,IQUNST,IQUNIT,IQUNUM,IQFSTN,IQLMAX,IQLCLM,
     *IQLNNO,IQLPGE
      COMMON /IQCHRA/IQCDAT,IQVDAT,IQLCNT,IQLINE
      CALL IQSCHR
      CALL IQDATE(IQCDAT(1:8))
      CALL IQTIME(IQCDAT(9:16))
      CALL IQINST(IQCDAT(17:24))
      DO 1001 I=1,3
      IQLINE (I)=' '
      IQLCLM (I)=1
      IQLPGE (I)=0
      IQLCNT (I)=' '
      IQLNNO (I)=0
 1001 CONTINUE
 1002 IQLMAX (1)=132
      IQLMAX (2)=72
      IQLMAX (3)=132
      IQFSTN =0
 1000 RETURN
      END
      SUBROUTINE IQCBUF
*     GENERATED BY FPL90 V(AIX V3.0 94- 1- 7)        AIX V3.0 94- 1-29
      IMPLICIT INTEGER(A-Z)
