     *IQLNNO,IQLPGE
      COMMON /IQCHRA/IQCDAT,IQVDAT,IQLCNT,IQLINE
      UNITNO =IQUNIT
      IQUNIT =0
 1001 IF (.NOT.(IQUNIT.LE.3))GO TO 1002
