 1000 RETURN
      END
      SUBROUTINE IQEXIT
*     GENERATED BY FPL90 V(AIX V3.0 94- 1- 7)        AIX V3.0 94- 1-29
      IMPLICIT INTEGER(A-Z)
      CALL IQCBUF
      IF (.NOT.(.TRUE.))GO TO 1001
      STOP
 1001 CONTINUE
 1000 RETURN
      END
