      INTEGER NCH
      CHARACTER ISYMB*(*)
      IF (.NOT.(IQLCLM(IQUNIT)+NCH-1.GT.IQLMAX(IQUNIT)))GO TO 1001
      CALL IQEMIT
      IF (.NOT.(IQUNIT.EQ.2))GO TO 1003
      IQLCLM (2)=7
      IQLINE (2)(6:6)='*'
 1004 CONTINUE
 1003 CONTINUE
 1002 CONTINUE
 1001 ICT =IQLCLM(IQUNIT)
      IQLCLM (IQUNIT)=ICT+NCH
      ICMAX =ICT+NCH-1
      IQLINE (IQUNIT)(ICT:ICMAX)=ISYMB
